class Solution:
    def removeBoxes(self, boxes) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dp(l, r, k):
            if l > r: return 0
            while r > l and boxes[r]==boxes[r-1]: r-=1; k+=1
            res = dp(l,r-1,0)+(k+1)**2
            for i in range(l,r):
                if boxes[i]==boxes[r]: res=max(res,dp(l,i,k+1)+dp(i+1,r-1,0))
            return res
        return dp(0,len(boxes)-1,0)

class Solution:
    def splitArray(self, nums) -> bool:
        n = len(nums)
        if n < 7: return False
        p = [0]*(n+1)
        for i in range(n): p[i+1]=p[i]+nums[i]
        for j in range(3,n-3):
            s = set()
            for i in range(1,j-1):
                if p[i]==p[j]-p[i+1]: s.add(p[i])
            for k in range(j+2,n-1):
                if p[k]-p[j+1]==p[n]-p[k+1] and p[k]-p[j+1] in s: return True
        return False

class Solution:
    def longestConsecutive(self, root) -> int:
        self.ans = 0
        def dfs(node):
            if not node: return 0,0
            inc=dec=1
            for c in [node.left,node.right]:
                if not c: continue
                ci,cd = dfs(c)
                if c.val==node.val+1: inc=max(inc,ci+1)
                if c.val==node.val-1: dec=max(dec,cd+1)
            self.ans=max(self.ans,inc+dec-1)
            return inc,dec
        dfs(root)
        return self.ans

