class Solution:
    def checkRecord(self, n: int) -> int:
        MOD=10**9+7
        dp=[[0]*3 for _ in range(2)]
        dp[0][0]=1
        for _ in range(n):
            nd=[[0]*3 for _ in range(2)]
            for a in range(2):
                for l in range(3):
                    if not dp[a][l]: continue
                    nd[a][0]=(nd[a][0]+dp[a][l])%MOD
                    if a<1: nd[a+1][0]=(nd[a+1][0]+dp[a][l])%MOD
                    if l<2: nd[a][l+1]=(nd[a][l+1]+dp[a][l])%MOD
            dp=nd
        return sum(dp[a][l] for a in range(2) for l in range(3))%MOD

