class Solution:
    def leastBricks(self, wall) -> int:
        from collections import Counter
        gaps = Counter()
        for row in wall:
            s = 0
            for b in row[:-1]:
                s += b
                gaps[s] += 1
        return len(wall) - (max(gaps.values()) if gaps else 0)

class Solution:
    def splitLoopedString(self, strs) -> str:
        arr = [max(s, s[::-1]) for s in strs]
        res = ''
        for i, s in enumerate(strs):
            rest = ''.join(arr[i+1:]+arr[:i])
            for cur in [s, s[::-1]]:
                for j in range(len(cur)):
                    cand = cur[j:]+rest+cur[:j]
                    if cand > res: res = cand
        return res

