class Solution:
    def findTilt(self, root) -> int:
        self.ans=0
        def dfs(n):
            if not n: return 0
            l,r=dfs(n.left),dfs(n.right)
            self.ans+=abs(l-r)
            return n.val+l+r
        dfs(root)
        return self.ans

class Solution:
    def nearestPalindromic(self, n: str) -> str:
        l = len(n)
        cands = set([10**l+1, 10**(l-1)-1])
        prefix = int(n[:(l+1)//2])
        for d in [-1,0,1]:
            p = str(prefix+d)
            if l%2: cand=p+p[:-1][::-1]
            else: cand=p+p[::-1]
            cands.add(int(cand))
        cands.discard(int(n))
        return str(min(cands, key=lambda x:(abs(x-int(n)),x)))

class Solution:
    def arrayNesting(self, nums) -> int:
        ans=0
        for i in range(len(nums)):
            if nums[i]<0: continue
            cnt=0; j=i
            while nums[j]>=0:
                nj=nums[j]; nums[j]=-1; j=nj; cnt+=1
            ans=max(ans,cnt)
        return ans

