class Solution:
    def maxVacationDays(self, flights, days) -> int:
        N,W=len(days),len(days[0])
        dp=[-1]*N; dp[0]=0
        for w in range(W):
            nd=[-1]*N
            for c in range(N):
                for fr in range(N):
                    if dp[fr]<0: continue
                    if fr==c or flights[fr][c]:
                        nd[c]=max(nd[c],dp[fr]+days[c][w])
            dp=nd
        return max(dp)

class Solution:
    def isSubtree(self, root, subRoot) -> bool:
        def same(a,b):
            if not a and not b: return True
            if not a or not b: return False
            return a.val==b.val and same(a.left,b.left) and same(a.right,b.right)
        if not root: return False
        return same(root,subRoot) or self.isSubtree(root.left,subRoot) or self.isSubtree(root.right,subRoot)

class Solution:
    def minDistance(self, height, width, tree, squirrel, nuts) -> int:
        total = sum(abs(n[0]-tree[0])+abs(n[1]-tree[1]) for n in nuts)*2
