class Solution:
    def findPaths(self, m, n, maxMove, startRow, startColumn) -> int:
        MOD=10**9+7
        dp=[[0]*n for _ in range(m)]
        dp[startRow][startColumn]=1
        ans=0
        for _ in range(maxMove):
            nd=[[0]*n for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    if not dp[i][j]: continue
                    for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ni,nj=i+di,j+dj
                        if 0<=ni<m and 0<=nj<n: nd[ni][nj]=(nd[ni][nj]+dp[i][j])%MOD
                        else: ans=(ans+dp[i][j])%MOD
            dp=nd
        return ans

class Solution:
    def killProcess(self, pid, ppid, kill):
        from collections import defaultdict, deque
        ch = defaultdict(list)
        for c,p in zip(pid,ppid): ch[p].append(c)
        res,q = [],[kill]
        while q:
            n = q.pop()
            res.append(n)
            q.extend(ch[n])
        return res

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m,n=len(word1),len(word2)
        dp=[[0]*(n+1) for _ in range(m+1)]
        for i in range(1,m+1):
            for j in range(1,n+1):
                if word1[i-1]==word2[j-1]: dp[i][j]=dp[i-1][j-1]+1
                else: dp[i][j]=max(dp[i-1][j],dp[i][j-1])
        return m+n-2*dp[m][n]

class Solution:
    def outerTrees(self, trees):
        def cross(O,A,B): return (A[0]-O[0])*(B[1]-O[1])-(A[1]-O[1])*(B[0]-O[0])
        pts=sorted(map(tuple,trees))
        if len(pts)<=2: return trees
        lo=[]
        for p in pts:
            while len(lo)>=2 and cross(lo[-2],lo[-1],p)<0: lo.pop()
            lo.append(p)
        up=[]
        for p in reversed(pts):
            while len(up)>=2 and cross(up[-2],up[-1],p)<0: up.pop()
            up.append(p)
        return [list(p) for p in set(lo+up)]

class FileSystem:
    def __init__(self):
        self.root={'dirs':{},'files':{}}
    def _nav(self,path):
        node=self.root
        for p in path.split('/')[1:]:
            if p: node=node['dirs'].setdefault(p,{'dirs':{},'files':{}})
        return node
    def ls(self,path):
        parts=path.split('/')
        node=self.root
        for p in parts[1:]:
            if p in node.get('files',{}): return [p]
            node=node['dirs'][p]
        return sorted(list(node['dirs'].keys())+list(node['files'].keys()))
    def mkdir(self,path): self._nav(path)
    def addContentToFile(self,path,content):
        parts=path.split('/')
        node=self._nav('/'.join(parts[:-1]))
        node['files'][parts[-1]]=node['files'].get(parts[-1],'')+content
    def readContentFromFile(self,path):
        parts=path.split('/')
        node=self._nav('/'.join(parts[:-1]))
        return node['files'][parts[-1]]

