class Solution:
    def postorder(self, root):
        if not root: return []
        res=[]
        for c in root.children: res.extend(self.postorder(c))
        res.append(root.val)
        return res

class Solution:
    def isValid(self, code: str) -> bool:
        import re
        code = re.sub(r'<!\[CDATA\[.*?\]\]>', 'c', code)
        prev = ''
        while code != prev:
            prev = code
            code = re.sub(r'<([A-Z]{1,9})>[^<]*</\1>', 't', code)
        return code == 't'

class Solution:
    def validSquare(self, p1, p2, p3, p4) -> bool:
        def d(a,b): return (a[0]-b[0])**2+(a[1]-b[1])**2
        ds = sorted([d(a,b) for i,a in enumerate([p1,p2,p3,p4]) for b in [p1,p2,p3,p4][i+1:]])
        return ds[0]>0 and ds[0]==ds[1]==ds[2]==ds[3] and ds[4]==ds[5]

class Solution:
