class Solution:
    def findRestaurant(self, list1, list2):
        idx={v:i for i,v in enumerate(list1)}
        mn=float('inf'); res=[]
        for j,v in enumerate(list2):
            if v in idx:
                s=j+idx[v]
                if s<mn: mn=s; res=[v]
                elif s==mn: res.append(v)
        return res
